  "after": "'use client';\n\nimport dynamic from 'next/dynamic';\nimport type { MapPoint } from '@/lib/wordpress';\n\n// Leaflet a besoin du DOM (window) : on charge la carte côté client uniquement.\nconst MapClient = dynamic(() => import('./MapClient').then((m) => m.MapClient), {\n  ssr: false,\n  loading: () => <div className=\"map-loading\" aria-hidden=\"true\" />,\n});\n\n// `labels` affiche les noms de lieux (page « Notre réseau ») ; la carte de\n// l'accueil reste sans libellés. `center`/`zoom` facultatifs : cadrage France.\nexport function NetworkMap({\n  points,\n  labels = false,\n  center,\n  zoom,\n}: {\n  points: MapPoint[];\n  labels?: boolean;\n  center?: [number, number];\n  zoom?: number;\n}) {\n  return (\n    <div className=\"map-shell\">\n      <MapClient points={points} labels={labels} center={center} zoom={zoom} />\n    </div>\n  );\n}\n"
